// Run first. Returns each collection that has at least one document, with its min_docs and its document count n.
// The caller keeps rows where n >= min_docs. GQ cannot compare an aggregate to another property of the outer row, so this comparison happens client-side.
query collection_doc_counts() {
    match {
        $c: Collection
        $d: Doc
        $d in $c
    }
    return {
        $c.slug,
        $c.min_docs,
        count($d) as n
    }
}
```

```gq
// Run second. Returns collections with min_docs <= 0, which any count satisfies, including collections with no documents that the first query cannot return.
// The caller adds these slugs to the slugs kept from the first query and removes duplicates.
query collections_needing_no_docs() {
    match {
        $c: Collection
        $c.min_docs <= 0
    }
    return { $c.slug }
}
